@Test
    public void to_populatesTextView() {
        TextView tv = new TextView(RuntimeEnvironment.application);

        Lex.say(R.string.this_is_a_template)
                .with(LexKey.SOMETHING, "test")
                .into(tv);

        assertEquals("This is a test.", tv.getText().toString());
    }

